async function executeLint(doc) {
    const controller = new AbortController();
    const signal = controller.signal;

    try {
        const response = await fetch('/v1/transform/wikitext/to/lint', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({ wikitext: doc.toString() }),
            signal: signal,
            timeout: MAX_TIMEOUT
        });

        if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
        }

        return await response.json();
    } catch (error) {
        if (error.name === 'AbortError') {
            mw.log.warn('[CodeMirror] Lint request aborted.');
        } else {
            mw.log.warn('[CodeMirror] Lint request failed:', error);
        }
        return null;
    } finally {
        controller.abort(); // Ensure the request is aborted
    }
}
