use Psr\SimpleCache\CacheInterface;

class AbstractWishlistStore {
    /** @var CacheInterface */
    private $cache;

    public function __construct(CacheInterface $cache) {
        $this->cache = $cache;
    }

    protected function getEntityFromCacheOrStore($key, callable $getter): mixed {
        if ($this->cache->has($key)) {
            return $this->cache->get($key);
        }
        $entity = $getter();
        $this->cache->set($key, $entity);
        return $entity;
    }
}

class FocusAreaStore extends AbstractWishlistStore {
    // ... other methods ...

    public function get($canonicalTitle, $preferredLanguage): FocusArea {
        $key = "focus_area_{$canonicalTitle}_{$preferredLanguage}";
        return $this->getEntityFromCacheOrStore($key, function () use ($canonicalTitle, $preferredLanguage) {
            /** @var FocusArea $entity */
            $entity = parent::get($canonicalTitle, $preferredLanguage);
            return $entity;
        });
    }
}
